const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Gobi Desert region (approximate center and bounds)
  const gobiDesert = ee.Geometry.Polygon([
    [[100, 38], [110, 38], [110, 46], [100, 46], [100, 38]]
  ]);

  // 2. Load MODIS AOD data for both periods
  const aod2019 = ee.ImageCollection('MODIS/061/MCD19A2_GRANULES')
    .filterDate('2019-02-01', '2019-03-01')
    .filterBounds(gobiDesert)
    .select('Optical_Depth_047');

  const aod2020 = ee.ImageCollection('MODIS/061/MCD19A2_GRANULES')
    .filterDate('2020-02-01', '2020-03-01')
    .filterBounds(gobiDesert)
    .select('Optical_Depth_047');

  const size2019 = await aod2019.size().getInfo();
  const size2020 = await aod2020.size().getInfo();

  console.log(`2019 Images: ${size2019}`);
  console.log(`2020 Images: ${size2020}`);

  // 3. Check if collections are empty
  if (size2019 === 0 || size2020 === 0) {
    console.log('Empty collection detected.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 4. Create median composites and scale AOD values
  const aod2019Mean = aod2019.mean().multiply(0.001); // Scale factor
  const aod2020Mean = aod2020.mean().multiply(0.001);

  // 5. Calculate mean AOD and pixel counts
  const stats2019 = await aod2019Mean.reduceRegion({
    reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
    geometry: gobiDesert,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const stats2020 = await aod2020Mean.reduceRegion({
    reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
    geometry: gobiDesert,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const mean2019 = stats2019.Optical_Depth_047_mean;
  const count2019 = stats2019.Optical_Depth_047_count;
  const mean2020 = stats2020.Optical_Depth_047_mean;
  const count2020 = stats2020.Optical_Depth_047_count;

  console.log(`2019 AOD: ${mean2019}, Pixels: ${count2019}`);
  console.log(`2020 AOD: ${mean2020}, Pixels: ${count2020}`);

  // 6. Validate results
  if (count2019 === 0 || count2020 === 0) {
    console.log('No valid pixels after processing.');
    console.log('<answer>C2</answer>');
    return;
  }

  if (mean2019 === null || mean2020 === null || 
      isNaN(mean2019) || isNaN(mean2020) ||
      mean2019 < 0 || mean2020 < 0 || mean2019 > 5 || mean2020 > 5) {
    console.log('Invalid AOD calculation.');
    console.log('<answer>C3</answer>');
    return;
  }

  // 7. Compare and answer
  if (mean2020 > mean2019) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
